arguments.command:
curl -s -X POST https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: Bearer <TOKEN>" -d '{"query":"{ issueType: __type(name: \"Issue\") { fields { name type { name kind ofType { name kind } } } } createInput: __type(name: \"IssueCreateInput\") { inputFields { name type { name kind ofType { name kind } } } } }"}' > /tmp/linear_schema.json; python3 - <<'EOF'
import json
d = json.load(open('/tmp/linear_schema.json'))
def show_type(t):
    if not t: return '?'
    out = []
    while t:
        n = t.get('name')
        k = t.get('kind')
        if n: out.append(n)
        if k == 'NON_NULL': out.append('!')
        elif k == 'LIST': out.append('[]')
        t = t.get('ofType')
    return ''.join(out)
for f in d['data']['issueType']['fields']:
    if 'priority' in f['name']:
        print('Issue.'+f['name'], show_type(f['type']))
for f in d['data']['createInput']['inputFields']:
    if f['name'] in ('id','priority','teamId','stateId','completedAt','title'):
        print('Input.'+f['name'], show_type(f['type']))
EOF

